#!/usr/bin/env python3
"""Generate the project's own INI from its frozen native tuning layout."""
import sys,json
from pathlib import Path
R=Path(__file__).resolve().parents[1];sys.path.insert(0,str(R/'tools'))
from engine_protocol import NUMBERS,FLAGS,CURVES,SIGNATURE,PAGE_SIZES,LIVE_FIELDS,REVISION_OFFSET,field_units
s=['; Generated by scripts/generate_tunerstudio_ini.py. Own ECU identity; not Speeduino firmware.','[MegaTune]',' MTversion = 2.25',' queryCommand = "Q"',f' signature = "{SIGNATURE.decode()}"',' versionInfo = "S"','[TunerStudio]',' iniSpecVersion = 3.64','[Constants]',' endianness = little',' nPages = 4',' pageSize = 512, 1152, 1152, 1152',' pageIdentifier = "\\$tsCanId\\x01", "\\$tsCanId\\x02", "\\$tsCanId\\x03", "\\$tsCanId\\x04"']
for key,value in [('pageReadCommand','p%2i%2o%2c'),('pageChunkWrite','M%2i%2o%2c%v'),('pageValueWrite','M%2i%2o%2c%v'),('burnCommand','b%2i'),('crc32CheckCommand','d%2i')]:s.append(' '+key+' = '+', '.join('"'+value+'"' for _ in range(4)))
s+=[' blockingFactor = 256',' messageEnvelopeFormat = msEnvelope_1.0',' tsWriteBlocks = on',' delayAfterPortOpen = 100',' blockReadTimeout = 2000',' page = 1']
for i,k in enumerate(FLAGS):s.append(f' {k} = bits, U32, 0, [{i}:{i}], "Off", "On"')
for i,(group,k) in enumerate(NUMBERS):
 unit=field_units(k)
 lo,hi=-1000,10000
 s.append(f' {k} = scalar, F32, {4+4*i}, "{unit}", 1, 0, {lo}, {hi}, 3')
offset=4+4*len(NUMBERS)
for k,n in CURVES:s.append(f' {k} = array, F32, {offset}, [{n}], "", 1, 0, -1000, 1000, 3');offset+=n*4
s.append(f' baseRevision = scalar, U32, {REVISION_OFFSET}, "", 1, 0, 1, 4294967295, 0')
for page,key,units,lo,hi in [(2,'ve','%',20,120),(3,'spark','deg',-5,40),(4,'lambda','lambda',.75,1.2)]:
 s += [f' page = {page}',f' {key}Rpm = array, F32, 0, [16], "RPM", 1, 0, 50, 10000, 0',f' {key}Load = array, F32, 64, [16], "kPa", 1, 0, 5, 110, 1',f' {key}Table = array, F32, 128, [16x16], "{units}", 1, 0, {lo}, {hi}, 2']
s+=['[OutputChannels]',' ochGetCommand = "r\\$tsCanId\\x30%2o%2c"',' ochBlockSize = 76']
for i,k in enumerate(LIVE_FIELDS):s.append(f' {k} = scalar, F32, {i*4}, "", 1, 0')
for offset,k in [(44,'faults'),(48,'sync'),(52,'physicalInhibited'),(56,'revision'),(60,'dataSource'),(64,'snapshotAgeMs'),(68,'simulationComplete'),(72,'hasResult')]:s.append(f' {k} = scalar, U32, {offset}, "", 1, 0')
groups={
 'engineSettings':('Engine and output limits',[k for group,k in NUMBERS if group=='engine']+['cranking_rpm','tooth1_btdc_deg','max_injection_ms','max_dwell_ms']),
 'engineEnrichment':('Starting and fuel corrections',['crank_advance_deg','afterstart_pct','afterstart_s','accel_threshold_pct_s','accel_gain','accel_decay_s','ego_enabled','ego_kp','ego_ki','ego_limit','ego_min_clt']),
 'engineProtection':('Rev limit and overrun cut',['rpm_limit','rpm_hysteresis','soft_limit_band','max_duty','dfco_enabled','dfco_rpm','dfco_hysteresis','dfco_tps','dfco_delay_s']),
 'engineAux':('Virtual auxiliary proposals',['idle_enabled','idle_target_rpm','idle_kp','idle_ki','fan_on_c','fan_off_c','pump_prime_s']),
}
s+=['[Menu]',' menuDialog = main',' menu = "Engine development"']
for key,(label,fields) in groups.items():s.append(f' subMenu = {key}, "{label} (shadow only)"')
for key,label in [('ve','VE map'),('spark','Spark map'),('lambda','Lambda target')]:s.append(f' subMenu = {key}Editor, "{label}"')
for key,label in [('warmup','Warmup enrichment'),('crank','Cranking enrichment'),('deadtime','Injector dead time'),('dwell','Coil dwell')]:s.append(f' subMenu = {key}Curve, "{label}"')
s+=['[UiDialogs]']
for key,(label,fields) in groups.items():
 s.append(f' dialog = {key}, "{label} / PHYSICAL OUTPUTS INHIBITED"')
 for field in fields:s.append(f' field = "{field.replace("_"," ")}", {field}')
s+=['[CurveEditor]']
for key,label,axis,values,units in [('warmup','Warmup enrichment','coolant_c','warmup_pct','%'),('crank','Cranking enrichment','coolant_c','crank_pct','%'),('deadtime','Injector dead time','battery_v','deadtime_ms','ms'),('dwell','Coil dwell','battery_v','dwell_ms','ms')]:
 s += [f' curve = {key}Curve, "{label} (shadow only)"',f' columnLabel = "{axis}", "{label} ({units})"',f' xBins = {axis}',f' yBins = {values}']
s+=['[TableEditor]']
for k,label,lo,hi in [('ve','VE',20,120),('spark','Spark advance',-5,40),('lambda','Lambda target',.75,1.2)]:
 s += [f' table = {k}Editor, {k}Map, "{label} (shadow only)", {1 if k=="ve" else 2 if k=="spark" else 3}',f' xBins = {k}Rpm, rpm',f' yBins = {k}Load, map_kpa',f' zBins = {k}Table',f' upDownLabel = "{label}"',f' gridHeight = 2.0',f' gridOrient = 250, 0, 340']
s+=['[GaugeConfigurations]',' rpmGauge = rpm, "Engine speed", "RPM", 0, 8000, 0, 0, 6500, 8000, 0, 0',' mapGauge = map_kpa, "Manifold pressure", "kPa", 0, 110, 0, 10, 105, 110, 1, 1',' pwGauge = pulse_ms, "Proposed injection", "ms", 0, 15, 0, 0, 14, 15, 2, 2',' advanceGauge = advance_deg, "Proposed advance", "deg", -5, 40, -5, 0, 35, 40, 1, 1','[FrontPage]',' gauge1 = rpmGauge',' gauge2 = mapGauge',' gauge3 = pwGauge',' gauge4 = advanceGauge',' indicator = { physicalInhibited }, "PHYSICAL OUTPUTS INHIBITED", "PHYSICAL OUTPUTS INHIBITED", yellow, black, yellow, black',' indicator = { hasResult }, "NO SIL RESULT", "COMPLETED SIL SNAPSHOT", gray, black, yellow, black','[Datalog]']
for k in LIVE_FIELDS:s.append(f' entry = {k}, "{k}", float, "%.4f"')
s+=[' entry = faults, "Faults", int, "%d"',' entry = physicalInhibited, "PhysicalInhibited", int, "%d"']
(R/'tuning/esp32-ecu-sil.ini').write_text('\n'.join(s)+'\n')
(R/'tuning/protocol-layout.json').write_text(json.dumps(dict(signature=SIGNATURE.decode(),pages=PAGE_SIZES,numeric_fields=NUMBERS,flags=FLAGS,curves=CURVES,live_fields=LIVE_FIELDS,live_block_bytes=76,scope='native SIL transport only; physical UART is not implemented'),indent=2)+'\n')
print('Generated own TunerStudio INI and wire-layout manifest')
